const body = $input.first().json;
if (!Array.isArray(body.projects)) {
  throw new Error('No projects array in response: ' + JSON.stringify(body).slice(0, 300));
}
return body.projects.map(p => ({
  json: {
    project_id: p.project_id,
    name: p.name,
    url: 'https://api.lokalise.com/api2/projects/' + p.project_id + '/languages?limit=100&page=1'
  }
}));

const meta = {};
for (const it of $('Expand projects').all()) {
  meta[String(it.json.project_id)] = it.json.name;
}

const rows = [];
for (const it of $input.all()) {
  const b = it.json;
  const pid = String(b.project_id || '');
  if (!Array.isArray(b.languages)) {
    throw new Error('No languages array for project ' + pid + ': ' + JSON.stringify(b).slice(0, 200));
  }
  for (const l of b.languages) {
    rows.push({
      pid,
      pname: meta[pid] || pid,
      lang_id: l.lang_id,
      lang_iso: l.lang_iso,
      lang_name: l.lang_name
    });
  }
}

const byIso = {};
const byId = {};
for (const r of rows) {
  const iso = r.lang_iso;
  byIso[iso] = byIso[iso] || {};
  byIso[iso][r.lang_id] = byIso[iso][r.lang_id] || { names: {}, projects: [] };
  byIso[iso][r.lang_id].names[r.lang_name] = true;
  byIso[iso][r.lang_id].projects.push(r.pname);

  byId[r.lang_id] = byId[r.lang_id] || {};
  byId[r.lang_id][iso] = byId[r.lang_id][iso] || { names: {}, projects: [] };
  byId[r.lang_id][iso].names[r.lang_name] = true;
  byId[r.lang_id][iso].projects.push(r.pname);
}

const out = [];

for (const iso of Object.keys(byIso).sort()) {
  const ids = Object.keys(byIso[iso]);
  const allNames = {};
  const idDetail = ids.map(id => {
    Object.keys(byIso[iso][id].names).forEach(n => { allNames[n] = true; });
    return {
      lang_id: Number(id),
      lang_names: Object.keys(byIso[iso][id].names),
      project_count: byIso[iso][id].projects.length,
      projects: byIso[iso][id].projects.sort()
    };
  });
  const nameList = Object.keys(allNames);
  const conflict = ids.length > 1 || nameList.length > 1;
  out.push({
    json: {
      kind: 'iso',
      lang_iso: iso,
      distinct_id_count: ids.length,
      distinct_name_count: nameList.length,
      conflict,
      lang_names: nameList,
      ids: conflict ? idDetail : idDetail.map(d => ({
        lang_id: d.lang_id,
        lang_names: d.lang_names,
        project_count: d.project_count
      }))
    }
  });
}

for (const id of Object.keys(byId).sort((a, b) => Number(a) - Number(b))) {
  const isos = Object.keys(byId[id]);
  if (isos.length > 1) {
    out.push({
      json: {
        kind: 'id_reused_across_isos',
        lang_id: Number(id),
        isos: isos.map(i => ({
          lang_iso: i,
          lang_names: Object.keys(byId[id][i].names),
          project_count: byId[id][i].projects.length,
          projects: byId[id][i].projects.sort()
        }))
      }
    });
  }
}

const perProject = {};
for (const r of rows) {
  perProject[r.pname] = (perProject[r.pname] || 0) + 1;
}

out.push({
  json: {
    kind: 'summary',
    projects_fetched: Object.keys(perProject).length,
    projects_expected: $('Expand projects').all().length,
    language_rows: rows.length,
    distinct_isos: Object.keys(byIso).length,
    distinct_ids: Object.keys(byId).length,
    per_project_language_count: perProject
  }
});

return out;
